  _ = `%2$s încep pe %3$s. Dacă dorești să participi la %2$s, durata ofertei zilnice nu ar trebui să depășească %1$s zi.`,
  _ = `%2$s încep pe %3$s. Dacă dorești să participi la %2$s, durata ofertei zilnice nu ar trebui să depășească %1$s zile.`,
  _ = `Consultă documentația`,
