  _ = `Articolul pentru evidențiere:`,
  _ = `Acest articol va apărea în locul destinat ofertei zilnice cu prețul, reducerea și imaginea capsulei. În cele mai multe situații, îți recomandăm să utilizezi selecția implicită a jocului.`,
