  _ = `Eroare: nu există niciun joc eligibil pentru această ofertă zilnică.`,
  _ = `Selectează o aplicație`,
  _ = `Mai multe dintre aplicațiile tale au fost invitate pentru a participa la oferta zilnică. Te rugăm să selectezi aplicația pe care dorești s-o utilizezi pentru data selectată.`,
