  _ = `Alege o dată și înregistrează-te înainte de %1$s`,
  _ = `Introdu reducerile`,
  _ = `Modifică reducerile`,
  _ = `Mai întâi trebuie să selectezi o dată`,
  _ = `Această ofertă zilnică este ACTIVĂ!`,
  _ = `Această ofertă zilnică s-a încheiat pe %1$s`,
  _ = `Oferta zilnică nu a fost afișată, deoarece nu a existat nicio reducere pentru joc la momentul respectiv.`,
  _ = `Această ofertă zilnică a fost anulată`,
  _ = `Această invitație a fost anulată`,
  _ = `Cum funcționează invitațiile?`,
  _ = `Dacă jocul tău este invitat să participe la o ofertă zilnică, vei primi un e-mail și vei vedea jocul tău listat mai sus. Iată cum funcționează procesul din acel moment:`,
  _ = `Alege o dată disponibilă din următoarele 6 luni care îți este convenabilă.`,
  _ = `Promoția ta va fi evidențiată pe pagina principală Steam și pe paginile etichetelor asociate timp de 24 de ore, iar reducerea va fi activă pentru o perioadă cuprinsă între 7 și 14 zile, în funcție de durata pentru care ai optat. Promoția va începe la ora 10:00 (ora Pacificului) a zilei selectate.`,
  _ = `Atunci când selectezi o dată disponibilă, ți se va cere să introduci un procent de reducere și să selectezi pachetele pe care dorești să le incluzi în ofertă.`,
  _ = `Ți se cere să alegi un procent de reducere care să fie cel puțin egal cu cea mai mare reducere pe care ai oferit-o în trecut, dacă nu chiar mai mare.`,
  _ = `Dacă nu ai totul pregătit pentru a-ți programa oferta zilnică acum, poți accesa oricând invitația din panoul tău de control pentru oferta zilnică. Te rugăm să ții cont de data de expirare.`,
  _ = `%1$s dacă vrei să-ți modifici data, să anulezi promoția sau ai alte întrebări.`,
  _ = `Contactează-ne aici`,
  _ = `Cele mai bune practici pentru oferta zilnică`,
  _ = `Am constatat că este avantajos să sincronizezi vizibilitatea crescută și reducerea cu alte activități deja planificate, cum ar fi o actualizare a conținutului de joc, transmisiuni în direct sau un eveniment în cadrul comunității.`,
  _ = `Dacă ai și alte reduceri planificate în interval de o lună de la oferta zilnică pe care ai selectat-o, încearcă să oferi același procent de reducere pentru toate aceste evenimente. Când îți evidențiem titlul ca o ofertă zilnică, ne dorim ca reducerea ta să fie cel puțin egală cu cele pe care le-ai oferit anterior.`,
  _ = `Pentru mai multe informații, te rugăm să consulți <1>documentația despre ofertele zilnice</1>.`,
  _ = `Vizibilitate`,
  _ = `Secțiunea „Oferta zilnică” de pe pagina principală a aplicației Steam utilizează imaginea capsulei de antet a jocului tău.`,
  _ = `Informații despre evenimentul de reduceri`,
