  _ = `Se încarcă reducerile pachetului`,
  _ = `Reducere existentă:`,
  _ = `Acest %1$s va fi evidențiat ca ofertă zilnică la această dată, utilizând reducerea existentă (%2$s).`,
  _ = `Dacă dorești să creezi o reducere nouă pentru această ofertă zilnică, te rugăm să ștergi reducerea existentă: accesează %1$s și introdu valoarea 0 pentru reducerea procentuală sau selectează o dată diferită pentru oferta zilnică.`,
  _ = `panoul tău de control pentru reduceri`,
  _ = `Există un conflict privind perioada de restricție pentru un pachet din acest set.`,
  _ = `Aplicație:`,
  _ = `Pagină de creator`,
  _ = `Pagină promoțională`,
  _ = `Pentru a selecta o pagină promoțională, ai nevoie de acces în calitate de deținător sau responsabil pentru o pagină de creator. Dacă organizația ta nu are o pagină de creator, %1$s.`,
  _ = `A apărut o eroare la crearea paginii promoționale`,
