  _ = `Ofertă de weekend`,
  _ = `%1$s – Invitație`,
  _ = `Eroare: tip de invitație neașteptat. Te rugăm să contactezi asistența Steam.`,
  _ = `Această invitație a expirat. NU mai poți realiza nicio acțiune.`,
  _ = `Te rugăm să alegi o dată cuprinsă în următoarele %1$s luni pentru ca jocul tău să fie prezentat sub forma unei oferte săptămânale.`,
  _ = `Te rugăm să alegi o dată cuprinsă în următoarele %1$s luni pentru ca jocul tău să fie prezentat sub forma unei oferte de weekend.`,
  _ = `Alege o dată disponibilă din următoarele %1$s luni care îți este convenabilă.`,
  _ = `Promoția ta va fi evidențiată pe pagina principală Steam și pe paginile etichetelor asociate timp de %1$s zile, iar reducerea va fi activă pentru o perioadă cuprinsă între 7 și 14 zile, în funcție de durata pentru care ai optat. Promoția va începe la ora 10:00 (ora Pacificului) a zilei selectate.`,
  _ = `Atunci când selectezi o dată disponibilă, ți se va cere să introduci un procent de reducere și să selectezi pachetele pe care dorești să le incluzi în ofertă.`,
  _ = `Ți se cere să alegi un procent de reducere care să fie cel puțin egal cu cea mai mare reducere pe care ai oferit-o în trecut, dacă nu chiar mai mare.`,
  _ = `Dacă nu ai totul pregătit pentru a-ți programa oferta săptămânală acum, poți accesa oricând invitația din panoul tău de control. Te rugăm să ții cont de data de expirare.`,
  _ = `Dacă nu ai totul pregătit pentru a-ți programa oferta de weekend acum, poți accesa oricând invitația din panoul tău de control. Te rugăm să ții cont de data de expirare.`,
  _ = `Cele mai bune practici`,
  _ = `Dacă ai și alte reduceri planificate în interval de o lună de la oferta săptămânală pe care ai selectat-o, încearcă să oferi același procent de reducere pentru toate aceste evenimente. Când îți evidențiem titlul ca o ofertă săptămânală, ne dorim ca reducerea ta să fie cel puțin egală cu cele pe care le-ai oferit anterior.`,
  _ = `Dacă ai și alte reduceri planificate în interval de o lună de la oferta de weekend pe care ai selectat-o, încearcă să oferi același procent de reducere pentru toate aceste evenimente. Când îți evidențiem titlul ca o ofertă de weekend, ne dorim ca reducerea ta să fie cel puțin egală cu cele pe care le-ai oferit anterior.`,
  _ = `Pentru mai multe informații, te rugăm să consulți <1>documentația despre ofertele săptămânale</1>.`,
