  _ = `Trimite spre verificare până pe %1$s.`,
  _ = `Versiunea compilată a demoului tău trebuie să treacă testul nostru de verificare pentru a putea participa la Festivalul Next. Reține că acest proces de verificare se asigură că demoul rulează și că acesta conține caracteristicile promise. Prin urmare, acesta nu este un proces complet de asigurare a calității, așa că testează-ți în continuare demoul.`,
