  _ = `Citește documentația`,
  _ = `Clasificările de vârstă necesare pentru ca jocurile să fie comercializate în Germania: 15 noiembrie`,
  _ = `Uneia dintre aplicațiile tale îi lipsește clasificarea de vârstă pentru Germania. Începând cu 15 noiembrie 2024, Steam nu va mai afișa titlul respectiv clienților care accesează magazinul Steam în Germania. Pentru a te asigura că jocurile tale vor continua să fie comercializate în Germania, te rugăm să completezi și să publici rezultatul chestionarului Steam privind conținutul.`,
  _ = `Mai multora dintre aplicațiile tale le lipsește clasificarea de vârstă pentru Germania. Începând cu 15 noiembrie 2024, Steam nu va mai afișa titlurile respective clienților care accesează magazinul Steam în Germania. Pentru a te asigura că jocurile tale vor continua să fie comercializate în Germania, te rugăm să completezi și să publici rezultatul chestionarului Steam privind conținutul.`,
