  _ = `Adrese de e-mail de contact`,
  _ = `Adaugă-ți adresa de contact sau pe cea a unui coleg pentru a te asigura că primiți e-mailuri importante de la Steam.`,
  _ = `În prezent, nu este configurat niciun utilizator pentru a primi comunicări Steamworks. Te rugăm să acorzi permisiunea „Primirea de comunicări Steamworks” unuia sau mai multor utilizatori de mai jos care au o adresă de e-mail validă, astfel încât Steam să le poată trimite notificări cu privire la campanii promoționale viitoare, evenimente, noi caracteristici sau alte invitații speciale.`,
  _ = `Gestionează permisiunile`,
