  _ = `Adresă poștală solicitată`,
  _ = `Valve ar dori să-ți trimită ceva. Te rugăm să ne furnizezi o adresă poștală sau să refuzi solicitarea până la data de %1$s.`,
  _ = `Valve ar dori să-ți trimită ceva. Termenul-limită era %1$s, dar încă poți să ne furnizezi o adresă poștală sau să refuzi solicitarea.`,
  _ = `Valve ar dori să-ți trimită ceva. Te rugăm să ne furnizezi o adresă poștală sau să refuzi solicitarea.`,
  _ = `Introdu adresa`,
  _ = `Adresă poștală`,
  _ = `Adăugarea unei adrese de corespondență ne va permite să-ți livrăm bunuri fizice și ne va fi de ajutor atunci când vom alege locațiile optime pentru evenimentele Steamworks viitoare.`,
  _ = `Această adresă poate fi diferită de cea pe care ai furnizat-o atunci când te-ai înregistrat pe Steamworks. Dacă există mai multe locații în care afacerea ta își desfășoară activitatea, iar acestea utilizează același cont de Steamworks, te rugăm să introduci fiecare locație separat.`,
