  _ = `Pentru a insera imagini în editorul de aici, încarcă-le pentru început în secțiunea „Încarcă imagini personalizate” de mai jos. Apoi, amplasează mouse-ul pe imaginea încărcată și apasă butonul „Copiază numele imaginii în clipboard” %1$s. Lipește apoi numele în interiorul etichetelor [img][/img] în cadrul câmpului de descriere de aici.`,
