  _ = `Antitrișare`,
  _ = `Dacă jocul tău instalează pe sistemul client software antitrișare la nivelul nucleului sistemului de operare, va trebui să dezvălui aici acest lucru utilizatorilor. Dacă ai propria ta soluție antitrișare sau dacă aceasta nu apare în lista de mai jos, selectează „Alt serviciu” și introdu propriile informații.`,
  _ = `Dacă jocul tău conține o soluție antitrișare, fie pe sistemul client, fie pe server, care nu este instalată la nivel de nucleu, completarea acestui câmp este opțională, dar, în general, credem că ar fi benefic ca orice joc care folosește o tehnologie antitrișare să informeze jucătorii despre acest fapt.`,
