  _ = `Această soluție antitrișare implică instalarea sau modificarea de fișiere la nivelul nucleului sistemului de operare.`,
  _ = `Această soluție antitrișare nu modifică fișiere la nivelul nucleului sistemului de operare.`,
  _ = `Te rugăm să selectezi dacă soluția ta antitrișare instalează fișiere la nivelul nucleului sistemului de operare pentru oricare dintre modurile jocului tău.`,
  _ = `Se dezinstalează complet`,
  _ = `Selectează această opțiune numai dacă poți confirma că toate fișierele pe care jocul tău le-a instalat sunt eliminate de pe disc atunci când jocul este dezinstalat.`,
  _ = `Protecție la pornire necesară`,
  _ = `Dacă jocul tău necesită pornire securizată, un TPM sau alte măsuri de protecție la pornire activate pentru oricare dintre modurile de joc, te rugăm să indici combinația necesară.`,
  _ = `Nimic`,
  _ = `Pornire securizată și TPM 2.0`,
  _ = `Nu utilizează un serviciu antitrișare`,
  _ = `Easy Anti-Cheat`,
  _ = `Denuvo`,
  _ = `BattlEye`,
  _ = `XIGNCODE3`,
  _ = `PunkBuster`,
  _ = `VAC (Valve Anti-Cheat)`,
  _ = `nProtect GameGuard`,
  _ = `HackShield`,
  _ = `Anti-Cheat Expert (ACE)`,
  _ = `SARD Anti-Cheat`,
  _ = `HProtect`,
  _ = `Alt serviciu`,
  _ = `Toate platformele`,
  _ = `Windows`,
  _ = `Bifează această căsuță dacă nu este necesar niciun redistribuibil`,
  _ = `Unreal Engine necesită, de obicei, Visual C++. Unele jocuri UE pot necesita, de asemenea, DirectX.`,
  _ = `Grupează edițiile`,
  _ = `Explică diferențele dintre ediții...`,
  _ = `Această interfață îți permite să furnizezi o imagine pentru a descrie diferențele dintre edițiile jocului tău (de exemplu, „Standard” vs „Deluxe” vs „Jocul anului”). Edițiile vor fi grupate alături de jocul de bază în partea de sus a opțiunilor de achiziție și vor fi afișate în ordine crescătoare, în funcție de preț, pe pagina din magazin. Pentru mai multe detalii, te rugăm să consulți <1>documentația „Explicarea diferențelor dintre ediții”</1>.`,
  _ = `Grupează mai multe ediții (Gold, Deluxe etc.) și adaugă, opțional, un grafic comparativ.`,
  _ = `(%1$s selectate ca ediții)`,
  _ = `Niciun grafic comparativ încărcat`,
  _ = `Grafic comparativ încărcat`,
  _ = `Ediție`,
  _ = `Titlul pachetului`,
  _ = `Pasul 1`,
  _ = `Pasul 2`,
  _ = `Pasul 3`,
  _ = `Stare`,
  _ = `Preț`,
  _ = `Explică diferențele dintre edițiile jocului tău`,
  _ = `Începe să tastezi pentru a filtra lista cu pachete`,
  _ = `Selectează pachetele care reprezintă ediții (de exemplu, Standard, Gold, Deluxe, Jocul anului etc.)`,
  _ = `Salvează`,
  _ = `Anulează`,
  _ = `Apasă sau trage o imagine aici pentru a o încărca`,
  _ = `Șterge`,
  _ = `Apasă sau trage o imagine aici pentru a înlocui această imagine.`,
  _ = `Încarcă o imagine cu dimensiuni de %1$s\xA0px × %2$s\xA0px care prezintă o comparație a edițiilor selectate. Această imagine va fi afișată într-o fereastră de dialog atunci când un utilizator apasă butonul „Compară edițiile” de pe pagina din magazin a aplicației tale. Utilizează meniul vertical pentru limbi pentru a încărca versiuni localizate ale imaginii tale.`,
  _ = `Odată ce salvezi modificările pentru magazin, trebuie să le <1>publici</1> pentru a le face vizibile utilizatorilor.`,
  _ = `Reține că trebuie să <1>publici</1> modificările.`,
  _ = `Imaginile comparative trebuie să aibă o dimensiune de %1$s x %2$s pixeli. Imaginea furnizată are o dimensiune de %3$s x %4$s.`,
  _ = `Edițiile trebuie să includă jocul de bază („%1$s”, ID-ul de pachet %2$s).`,
  _ = `Imaginile nu au dimensiunile corecte pentru următoarele limbi: %1$s`,
  _ = `Se salvează modificările aduse edițiilor`,
  _ = `Salvat!`,
  _ = `OK`,
  _ = `Se salvează modificările.`,
  _ = `Introdu textul alternativ care va fi utilizat de cititoarele de ecran pentru a descrie imaginea. Scrie textul într-o manieră care să-i explice utilizatorului care sunt diferențele dintre edițiile pe care le oferi.`,
  _ = `Reguli pentru resursele grafice`,
  _ = `Înainte de a continua, te rugăm să confirmi că imaginile tale respectă standardele impuse. Dacă trimiți imaginile spre verificare, iar acestea nu respectă cerințele, echipa Steam responsabilă de verificare nu le va putea aproba și va trebui să le corectezi înainte de a continua. Pentru mai multe detalii, te rugăm să consulți documentația <1>Reguli pentru resursele grafice</1>.`,
  _ = `Confirmă și încarcă`,
  _ = `Confirm faptul că această capsulă conține un logo vizibil (acesta ar trebui să umple majoritatea imaginii).`,
  _ = `Confirm faptul că această capsulă conține nu conține alt text decât cel aferent logoului jocului.`,
  _ = `Confirm faptul că această capsulă conține un logo vizibil (acesta ar trebui să umple cel puțin o treime din imagine).`,
  _ = `Confirm faptul că această capsulă conține un logo care e suficient de mare, clar și vizibil.`,
  _ = `Confirm faptul că acest logo e aplicat pe un fundal transparent.`,
  _ = `Confirm faptul că această imagine nu include texte sau logouri (logoul jocului tău trebuie încărcat separat ca o imagine PNG transparentă).`,
  _ = `Ordinea opțiunilor de achiziție`,
  _ = `Pachet`,
