  _ = `Antet`,
  _ = `Meniu vertical`,
  _ = `Alege pachetul`,
  _ = `Alege setul`,
  _ = `Setează manual ordinea opțiunilor de achiziție`,
  _ = `Dacă opțiunea este dezactivată, se va utiliza comportamentul anterior. Dacă este activată, va trebui să ordonezi manual toate opțiunile de achiziție care vor apărea pe pagina din magazin a aplicației.`,
  _ = `N-a fost adăugată nicio opțiune de achiziție.`,
