  _ = `Descriere:`,
  _ = `Descrierea meniului vertical`,
  _ = `Articole:`,
  _ = `Selectează tipul opțiunii de achiziție.`,
  _ = `Trebuie să setezi textul antetului în cel puțin o limbă.`,
