  _ = `Selectează un set pentru această opțiune de achiziție.`,
  _ = `Furnizează un titlu pentru acest meniu vertical în cel puțin o limbă.`,
  _ = `Meniul vertical trebuie să conțină cel puțin două pachete sau seturi.`,
  _ = `Se încarcă...`,
  _ = `%1$s (%2$s)`,
  _ = `Prima opțiune de achiziție trebuie să fie un pachet care conține doar ID-ul de aplicație. Iată opțiunile disponibile:`,
  _ = `(Precomandă)`,
  _ = `Nu se aplică`,
  _ = `Pasul 1`,
  _ = `Selectează pachetele pe care vrei să le lansezi sau să le retragi:`,
  _ = `Jocul de bază:`,
  _ = `Alte acțiuni care vor fi efectuate:`,
  _ = `Modifică mențiunea de afișaj din magazinul Steam de la „În curând” la „Lansat”.`,
  _ = `Permite deținătorilor să descarce și să pornească jocul.`,
  _ = `Fă publică pagina din magazin a jocului și setează data și ora să fie ACUM`,
  _ = `Pasul 2`,
  _ = `Ești gata să-ți lansezi jocul chiar acum?`,
