  _ = `Stabilirea prețurilor`,
  _ = `Lansează-mi aplicația`,
  _ = `Dacă ești pregătit să-ți lansezi aplicația și s-o faci disponibilă imediat pentru clienți, te rugăm să scrii propoziția „%1$s” în căsuța de mai jos.`,
  _ = `Lansează acum`,
