  _ = `Salvează`,
  _ = `Anulează`,
  _ = `Editează conținutul non-aplicație`,
  _ = `Numele afișat (maxim 120 de caractere)`,
  _ = `Textul din caseta cu informații`,
  _ = `Descriere (afișată la trecerea cu mouse-ul peste zona de achiziție a pachetului). Maxim 300 de caractere.`,
  _ = `Adaugă articol`,
  _ = `Salvate!`,
  _ = `Aceste modificări au fost salvate și publicate.`,
  _ = `OK`,
