  _ = `A apărut o eroare la salvarea și publicarea acestor modificări:`,
  _ = `Da`,
  _ = `Nu`,
  _ = `Nu există articole non-aplicație definite în acest pachet.`,
  _ = `Apasă „%1$s” pentru a adăuga o descriere pentru ceva din acest pachet care nu corespunde unui ID de aplicație.`,
  _ = `Vizibil pe pagina din magazin`,
  _ = `Prezentarea opțiunilor de achiziție a pachetului`,
  _ = `Afișează capsulele aplicațiilor în secțiunea de achiziție pentru acest pachet.`,
  _ = `(Pe pagina „Editează pachetul de magazin” de mai jos poți edita lista cu ilustrațiile de tip capsulă ale acestui pachet pe care dorești să le afișezi.)`,
  _ = `Ilustrația capsulei va fi adăugată în opțiunea de achiziție a pachetului din magazin, similar cu modul în care conținutul seturilor este afișat. Aplicația de bază va fi afișată prima, fiind urmată apoi de celelalte aplicații, în ordinea descrescătoare a prețurilor.`,
  _ = `Omite numele jocului din începutul denumirilor articolelor din lista cu conținutul pachetului.`,
  _ = `Pentru a reduce redundanța și a spori lizibilitatea, omite numele jocului, spațiile albe și semnele de punctuație de legătură, precum cele două puncte și cratima, din începutul denumirilor articolelor, precum DLC-urile și coloanele sonore, atunci când acestea sunt listate în secțiunea de achiziție a pachetului. De exemplu, „Half-Life 2: Episode 1” va fi afișat ca „Episode 1”. Doar numele exact al jocului de bază plus caracterele albe și semnele de punctuație obișnuite, precum cratimele și cele două puncte, vor fi ascunse.`,
  _ = `Salvează și publică`,
  _ = `Anulează`,
  _ = `Eveniment evidențiat pentru o actualizare importantă`,
  _ = `Deținătorii jocului vor fi redirecționați către evenimentul din bibliotecă pentru a vedea contextul. Evenimentele trebuie să fie atribuite jocului de bază.`,
  _ = `[Programat la %1$s] Numele evenimentului: %2$s`,
  _ = `[Schiță] Numele evenimentului: %2$s`,
  _ = `[A început la: %1$s] Numele evenimentului: %2$s`,
  _ = `Nu a fost găsit niciun eveniment eligibil. Necesită o schiță sau un eveniment postat recent (din ultima lună). <1>Consultă panoul de control pentru evenimente și anunțuri.</1>`,
  _ = `A fost salvată poziționarea logoului tău. Poți publica aceste modificări în cadrul secțiunii de gestionare a paginii din magazin.`,
  _ = `Gestionarea reducerilor`,
  _ = `Perioadele de desfășurare a promoțiilor pot suferi modificări. Fii prudent în ceea ce privește anunțarea publică a acestor date, în special pentru evenimentele care sunt programate peste un interval mare de timp.`,
  _ = `Note`,
  _ = `Reține faptul că nu este posibil să introduci o reducere în intervalul de 30 de zile de la lansarea unui joc pentru prima dată la preț întreg sau de la momentul creșterii prețului, indiferent de monedă. Pentru detalii suplimentare, te rugăm să consulți %1$s.`,
  _ = `documentația`,
  _ = `Reducerile încep și se încheie la ora 20:00 (UTC+2), dacă nu este menționat un alt program.`,
  _ = `Reducere personalizată`,
  _ = `Creează reducerea...`,
  _ = `+ creează`,
  _ = `Creează o reducere personalizată sau activează o ofertă cu durata de o săptămână în care să participe jocurile tale.`,
  _ = `Importă/exportă reducerile`,
  _ = `Instrumente`,
  _ = `Importă/exportă CSV...`,
  _ = `Stabilirea reducerilor pentru pachetele tale cu jocuri poate fi efectuată, de asemenea, prin modificarea unui fișier .csv. Această opțiune poate fi utilă dacă trebuie să actualizezi mai multe reduceri în același timp sau pentru a verifica uniformitatea prețurilor dintr-un catalog mai mare de jocuri.`,
  _ = `Descarcă tabelul cu reduceri din panoul de control sub forma unui fișier CSV. Acest tabel va include modificări în așteptare care nu au fost încă salvate.`,
  _ = `Descarcă-le pe toate`,
  _ = `Descarcă reducerile pentru toate pachetele.`,
  _ = `Descarcă reducerile vizibile`,
  _ = `Descarcă reducerile pentru pachetele vizibile, cu excepția celor pe care le-ai ascuns prin comprimarea rândurilor sau introducerea unui filtru de tip text.`,
  _ = `Încarcă un fișier CSV cu un tabel cu reducerile actualizate. Orice intrări care nu corespund reducerilor curente vor fi introduse în panoul de control drept modificări în așteptare. Poți previzualiza înainte de a trimite.`,
  _ = `Încarcă reducerile noi`,
  _ = `Încarcă și previzualizează noile reduceri.`,
  _ = `Importul este finalizat`,
  _ = `Au fost procesate %1$s pachete și and %2$s evenimente de reduceri.`,
  _ = `%1$s reducere a fost actualizată local.`,
  _ = `%1$s reduceri au fost actualizate local.`,
  _ = `Previzualizează acum modificările acestea înainte de a le salva sau apasă butonul OK pentru a reveni la panoul de control și a păstra modificările acestea în așteptare la nivel local.`,
  _ = `S-au găsit %1$s erori:`,
