  _ = `Programează o nouă reducere pentru un pachet.`,
  _ = `Selectează un pachet pentru a vedea opțiunile disponibile pentru reduceri.`,
  _ = `Toate oportunitățile de reduceri pentru acest pachet au fost rezervate pentru următoarele șase luni.`,
  _ = `Reducerea va începe și se va încheia automat la datele selectate. Odată ce o reducere începe, nu vei mai putea să o modifici, așa că îți recomandăm să planifici cu atenție.`,
  _ = `Acest pachet poate fi oferit cu o reducere de până la %1$s.`,
