  _ = `Cea mai recentă reducere: %1$s%`,
  _ = `Denumește această reducere personalizată mai jos și selectează datele din intervalul disponibil.`,
  _ = `Prețul acestui joc a fost majorat pentru una sau mai multe monede la data de %1$s. Din această cauză, este necesară scurgerea unei perioade minime de 30 de zile înainte de a aplica o reducere.`,
  _ = `De îndată ce ai salvat, poți adăuga pachete suplimentare la această reducere utilizând afișarea sub formă de grilă.`,
