  _ = `Înscrie-ți titlul`,
  _ = `Apasă mai jos pentru a-ți înscrie titlul la acest eveniment și a debloca posibilitatea introducerii de reduceri. Înregistrarea ta ne va permite să comunicăm informații importante despre eveniment pe măsură ce data acestuia se apropie. Poți anula oricând înregistrarea.`,
