  _ = `Nu poți seta o reducere mai mare de %1$s% pentru acest pachet deoarece prețul redus nu poate fi mai mic de 0,49 USD în orice monedă sau regiune.`,
  _ = `Prețul de bază al acestui pachet pentru una sau mai multe monede se află sub pragul minim permis. Drept urmare, nu poți introduce o reducere pentru acest pachet.`,
  _ = `Pachetele marcate cu acest simbol sunt adăugate unei reduceri deja existente. Aceste reduceri introduse vor fi aplicate imediat după salvare.`,
  _ = `Această reducere programată va determina ca prețul acestui pachet să se afle sub pragul minim de preț pentru una sau mai multe monede. Drept urmare, pachetul acesta nu va putea fi achiziționat din aceste țări. Pentru a te asigura că acest pachet poate fi achiziționat de oriunde, ar trebui să introduci o reducere procentuală mai mică de %1$s% pentru acest pachet.`,
  _ = `Prețul de bază al acestui pachet pentru una sau mai multe monede se află sub pragul minim permis. Drept urmare, acest pachet nu va fi disponibil pentru achiziție în țările pentru care prețul final al produsului, în urma aplicării reducerii, se va afla sub pragurile minime acceptate. Pentru a te asigura că acest pachet poate fi achiziționat de oriunde, te rugăm să actualizezi prețurile acestuia astfel încât acestea să fie cel puțin egale cu pragurile minime impuse de Steam.`,
  _ = `Ai o modificare nesalvată. Dacă renunți acum, reducerile noi vor fi anulate, iar reducerile actualizate vor reveni la setările anterioare.`,
  _ = `Ai %1$s modificări nesalvate. Dacă renunți acum, reducerile noi vor fi anulate, iar reducerile actualizate vor reveni la setările anterioare.`,
  _ = `Vizitează pagina principală a aplicației`,
  _ = `DETALIILE EVENIMENTULUI`,
  _ = `MODUL TĂU DE VIZUALIZAREA A ACESTUI EVENIMENT`,
  _ = `Începe: %1$s`,
  _ = `Se încheie: %1$s`,
  _ = `Momentan sunt afișate %1$s din %2$s pachete eligibile`,
  _ = `Ascunde pachetele care prezintă conflicte`,
  _ = `Poți filtra în funcție de numele pachetului sau restrânge secțiunile jocului din partea stângă.`,
  _ = `APLICĂ REDUCERI LA TOATE PACHETELE VIZIBILE`,
  _ = `Introdu o reducere cuprinsă între 10% și 95%.`,
  _ = `De asemenea, poți introduce numărul 0 pentru a elimina reducerile de la toate pachetele vizibile.`,
  _ = `Această acțiune va introduce o reducere pentru toate pachetele vizibile și va înlocui totodată orice reducere existentă specificată. Acest lucru este similar cu introducerea valorii în fiecare casetă separat. Vei avea în continuare ocazia de a previzualiza și de a confirma acest lucru înainte ca modificările să fie aplicate.`,
  _ = `NOTĂ: reducerea maximă pentru cel puțin unul din aceste pachete este de %1$s%.`,
  _ = `Află mai multe`,
  _ = `APLICĂ PENTRU UN PACHET`,
  _ = `APLICĂ PENTRU %1$s PACHETE`,
  _ = `Arată toate evenimentele`,
  _ = `Aceasta este o previzualizare a prețului tău în funcție de procentul de reducere introdus.`,
  _ = `VERSIUNEA BETA`,
  _ = `Trimite-ne feedbackul tău aici`,
  _ = `SALVEZI ÎNAINTE DE A CONTINUA?`,
  _ = `Ai modificări în așteptare care nu au fost salvate. Dorești să le salvezi înainte de a părăsi această pagină?`,
  _ = `Nu există niciun joc în pachet`,
  _ = `Aceste pachete fie conțin un DLC căruia îi lipsește linkul către jocul de bază, fie sunt aplicații care nu sunt jocuri, cum ar fi un video.`,
  _ = `Pachet cu mai multe jocuri`,
  _ = `pachet: %1$s`,
  _ = `1 pachet`,
  _ = `%1$s pachete`,
  _ = `Vizitează pagina principală a pachetului`,
  _ = `Pachetul acesta are prețuri pentru una sau mai multe monede care se află sub pragul minim permis. Derulează în dreapta pentru a vedea ce monede sunt afectate de acest avertisment.`,
  _ = `Pachetul acesta are una sau mai multe reduceri programate care vor duce la scăderea prețului jocului sub pragul minim permis, pentru una sau mai multe monede.`,
  _ = `Anulează modificarea în așteptare și revino la ultima valoare salvată`,
  _ = `Renunță și continuă`,
  _ = `ANULEZI MODIFICĂRILE ÎN AȘTEPTARE?`,
  _ = `ANULEAZĂ MODIFICĂRILE`,
  _ = `%1$s MODIFICARE ÎN AȘTEPTARE`,
  _ = `%1$s MODIFICĂRI ÎN AȘTEPTARE`,
  _ = `VEZI DETALIILE`,
