  _ = `Pe baza metodei de conversie selectate și a prețului în USD, prețul introdus este mult mai mic decât cel sugerat (%1$s). Acest preț va limita reducerile la cel mult %2$s%, astfel încât prețul redus să nu fie mai mic de 0,49 USD.`,
  _ = `Prețul introdus este cu %1$s mai mare decât prețul curent salvat.`,
